#include <iostream>
#include <queue>
#include <string>

using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    queue<int> q;
    long long current_sum = 0;
    for (int i = 0; i < n; ++i) {
        string op;
        cin >> op;
        if (op == "PUSH") {
            int x;
            cin >> x;
            q.push(x);
            current_sum += x;
        } else if (op == "POP") {
            if (!q.empty()) {
                current_sum -= q.front();
                q.pop();
            }
        } else if (op == "WEIGHT") {
            cout << current_sum << "\n";
        }
    }
    return 0;
}

