import sys

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    n = int(lines[0])
    queue = []
    results = []

    for i in range(1, n + 1):
        if i >= len(lines):
            break
        op = lines[i].strip()
        if op.startswith("PUSH"):
            parts = op.split()
            x = int(parts[1])
            queue.append(x)
        elif op == "POP":
            if queue:
                queue.pop(0)
        elif op == "WEIGHT":
            total_weight = sum(queue)
            results.append(str(total_weight))

    print('\n'.join(results))

if __name__ == '__main__':
    main()
